-- Errata reading for O14: Denominator = 2029 ED visits with a completed version (disposition known), as M22 (same question); an in-progress visit has no outcome and is not counted as "not admitted" (no inferred negatives).
WITH r AS MATERIALIZED (SELECT patient, payload FROM records WHERE stream='encounters'), e AS (SELECT json_extract(payload,'$.encounter_id') eid, min(json_extract(payload,'$.event_date')) d, max(CASE WHEN json_extract(payload,'$.disposition') IN ('admitted','inpatient_admission','hospital_observation','observation','observation_for_mobility') THEN 1 ELSE 0 END) adm , max(json_extract(payload,'$.status')='completed') done FROM r WHERE json_extract(payload,'$.type')='emergency' GROUP BY 1) SELECT round(100.0*sum(adm)/count(*),1) AS value FROM e WHERE done=1 AND d BETWEEN '2029-01-01' AND '2029-08-15';
